WITH filtered AS (SELECT *, LENGTH(dept_name) AS dept_name_length, COALESCE(dept_name, 'OTHER') AS resolved_dept_name FROM departments WHERE location IS NOT NULL AND dept_name = 'HR') SELECT id, dept_name, dept_name_length, LAST_VALUE(location) IGNORE NULLS OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_location, NTILE(5) OVER (PARTITION BY location ORDER BY dept_name_length, id) AS dept_name_length_bucket, AVG(budget) OVER (PARTITION BY dept_name ORDER BY dept_name_length, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS budget_avg_5_prior FROM filtered;
